!function(){"use strict";function anioFiscalCtrl($scope,mS,toast,form){let accion=JSON.parse(localStorage.getItem("accion"));null===accion?location.href="/Home/Index":$scope.accion=accion[0],$scope.data={},$scope.anios=[],$scope.totalRecords=0,$scope.pageIndex=1,$scope.pageSize=1e3,$scope.recordsQuantity=[5,10,25,50],$scope.options={boundaryLinks:!1,limitSelect:!0,pageSelect:!0},$scope.query={order:"descripcion",limit:10,page:1},$scope.get=function(){mS.getData("get","/AnioFiscal/Get?pageIndex="+$scope.pageIndex+"&pageSize="+$scope.pageSize).then(response=>{"0"!=response.id?$scope.anios=response.data:toast.toastr("warning",response.message,response.titleSms)},error=>console.log(error))},$scope.get(),$scope.pagechanged=function(){$scope.get()},$scope.changePageSize=function(){$scope.pageIndex=1,$scope.get()},$scope.abrirModal=function(data,type){$scope.type=type,$scope.colorHeader=1==type?"bg-info":"bg-success",$scope.icono=1==type?"fa fa-plus":"fa fa-edit",$scope.tituloModal=1==type?" Agregar Año Fiscal":" Actualizar Año Fiscal",$scope.btnTitulo=1==type?"Guardar":"Actualizar",$scope.btnColor=1==type?"btn-info":"btn-success",2==type&&($scope.data=data),$("#agregarAnioFiscal").modal("show")},$scope.save=function(type){if(form.campo($scope.data.descripcion))logger.warning("Por favor, ingrese el Año Fiscal",$scope.tituloModal);else{var url=1==type?"/AnioFiscal/Post":"/AnioFiscal/Put";mS.getData("post",url,$scope.data).then(response=>{if("0"!=response.id)return"1"==response.id?(toast.toastr("success",response.message,response.titleSms),$scope.get(),void $("#agregarAnioFiscal").modal("hide")):void 0;toast.toastr("warning",response.message,response.titleSms)})}},$scope.delete=function(data){Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar este registro ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!0}).then(result=>{result.value&&mS.getData("post","/AnioFiscal/Delete",data).then(response=>{if("0"!=response.id)return"1"==response.id?(toast.toastr("success",response.message,response.titleSms),void $scope.get()):void 0;toast.toastr("warning",response.message,response.titleSms)},error=>console.log(error))})},$(".modal").on("hide.bs.modal",(function(event){$scope.get(),$scope.data={}}))}angular.module("acontPlusApp").controller("anioFiscalCtrl",anioFiscalCtrl),anioFiscalCtrl.$inject=["$scope","mainService","toastService","formulario"]}();